package org.apache.commons.lang;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_createNumber_TriageGen2Test {

    @Test
    public void testCreateNumber_Null() throws NumberFormatException {
        assertNull(NumberUtils.createNumber(null));
    }

    @Test(expected = NumberFormatException.class)
    public void testCreateNumber_EmptyString() throws NumberFormatException {
        NumberUtils.createNumber("");
    }

    @Test
    public void testCreateNumber_DoubleDashProtection() throws NumberFormatException {
        assertNull(NumberUtils.createNumber("--123"));
    }

    @Test
    public void testCreateNumber_Hexadecimal() throws NumberFormatException {
        // Assuming createInteger handles hex
        assertEquals(Integer.valueOf(16), NumberUtils.createNumber("0x10"));
        assertEquals(Integer.valueOf(-16), NumberUtils.createNumber("-0x10"));
    }

    @Test
    public void testCreateNumber_IntegerTypes() throws NumberFormatException {
        assertEquals(Integer.valueOf(123), NumberUtils.createNumber("123"));
        assertEquals(Long.valueOf(123L), NumberUtils.createNumber("123"));
        assertEquals(new BigInteger("123456789012345678901234567890"), NumberUtils.createNumber("123456789012345678901234567890"));
    }

    @Test
    public void testCreateNumber_LongSuffix() throws NumberFormatException {
        assertEquals(Long.valueOf(123L), NumberUtils.createNumber("123l"));
        assertEquals(Long.valueOf(123L), NumberUtils.createNumber("123L"));
        // Fallback to BigInteger if too large for Long
        String largeLong = "9223372036854775808"; // Long.MAX_VALUE + 1
        assertEquals(new BigInteger(largeLong), NumberUtils.createNumber(largeLong + "L"));
    }

    @Test
    public void testCreateNumber_LongSuffixInvalid() {
        // Test cases where suffix is present but not a valid numeric structure
        try {
            NumberUtils.createNumber("1.2L");
            fail("Should have thrown NumberFormatException");
        } catch (NumberFormatException e) {
            assertTrue(e.getMessage().contains("is not a valid number"));
        }
    }

    @Test
    public void testCreateNumber_FloatSuffix() throws NumberFormatException {
        assertEquals(Float.valueOf(1.2f), NumberUtils.createNumber("1.2f"));
        assertEquals(Float.valueOf(1.2F), NumberUtils.createNumber("1.2F"));
    }

    @Test
    public void testCreateNumber_DoubleSuffix() throws NumberFormatException {
        assertEquals(Double.valueOf(1.2d), NumberUtils.createNumber("1.2d"));
        assertEquals(Double.valueOf(1.2D), NumberUtils.createNumber("1.2D"));
    }

    @Test
    public void testCreateNumber_DecimalTypes() throws NumberFormatException {
        assertEquals(new BigDecimal("1.2"), NumberUtils.createNumber("1.2"));
        assertEquals(new BigDecimal("1.2e2"), NumberUtils.createNumber("1.2e2"));
        assertEquals(new BigDecimal("1.2E2"), NumberUtils.createNumber("1.2E2"));
    }

    @Test
    public void testCreateNumber_ScientificNotationNoSuffix() throws NumberFormatException {
        // Should try Float -> Double -> BigDecimal
        assertEquals(Double.valueOf(1.2e2), NumberUtils.createNumber("1.2e2"));
    }

    @Test
    public void testCreateNumber_FloatPrecisionLoss() throws NumberFormatException {
        // A very precise number should bypass Float and Double and return BigDecimal
        String precise = "1.234567890123456789";
        Number result = NumberUtils.createNumber(precise);
        assertTrue(result instanceof BigDecimal);
        assertEquals(new BigDecimal(precise), result);
    }

    @Test
    public void testCreateNumber_FloatZeroPrecisionCheck() throws NumberFormatException {
        // Test the "allZeros" logic: if value is 0.0 but string has non-zeros, it shouldn't return float
        // e.g., "0.00000000000000000000000000000000001" might be 0.0 in float
        String tiny = "0.00000000000000000000000000000000001";
        Number result = NumberUtils.createNumber(tiny);
        assertTrue(result instanceof BigDecimal);
    }

    @Test
    public void testCreateNumber_InvalidExponentPosition() {
        // Case: expPos < decPos (e.g., "1e.2")
        // Note: The code logic for expPos calculation is: val.indexOf('e') + val.indexOf('E') + 1
        // This is a bit unusual, but we test the branch.
        try {
            NumberUtils.createNumber("1e.2");
            fail("Should have thrown NumberFormatException");
        } catch (NumberFormatException e) {
            // Expected
        }
    }

    @Test
    public void testCreateNumber_NonDigitLastCharNoSuffix() {
        // Test the default case in the switch when lastChar is not a digit and not a recognized suffix
        try {
            NumberUtils.createNumber("123?");
            fail("Should have thrown NumberFormatException");
        } catch (NumberFormatException e) {
            // Expected
        }
    }

    @Test
    public void testCreateNumber_NegativeNumbers() throws NumberFormatException {
        assertEquals(Integer.valueOf(-123), NumberUtils.createNumber("-123"));
        assertEquals(Long.valueOf(-123L), NumberUtils.createNumber("-123L"));
        assertEquals(new BigDecimal("-1.2"), NumberUtils.createNumber("-1.2"));
    }

    @Test
    public void testCreateNumber_ExponentWithSuffix() throws NumberFormatException {
        // Test scientific notation with suffix, e.g., 1.2e2f
        assertEquals(Float.valueOf(120.0f), NumberUtils.createNumber("1.2e2f"));
        assertEquals(Double.valueOf(120.0d), NumberUtils.createNumber("1.2e2D"));
    }
}
